"use strict";
window.WEBSEC_DATA_READY=(async()=>{
  if(typeof DecompressionStream!=="function")throw new Error("This browser does not support the WebSec Atlas data format.");
  const encoded="";
  const bytes=Uint8Array.from(atob(encoded),character=>character.charCodeAt(0));
  const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  const text=await new Response(stream).text();
  const topics=JSON.parse(text);
  if(!Array.isArray(topics)||topics.length!==105)throw new Error("Invalid WebSec Atlas data.");
  window.WEBSEC_TOPICS=topics;
  return topics;
})();
